from pathlib import Path
R=Path(__file__).resolve().parent.parent
out=['# -*- coding: utf-8 -*-']
for listen in (False,True):
 name='cs_accord_'+('listen' if listen else 'leave')
 choice='Остаться и послушать репетицию Мику' if listen else 'Поблагодарить Мику и пойти на линейку'
 out+=['testcase '+name+':','    pause 1.0','    $ renpy.set_physical_size((1280,720))','    $ _preferences.text_cps = 0','    $ _test.timeout = 40.0','    assert renpy.has_image("bg ext_musclub_day") and renpy.has_image("bg int_musclub_day")','    assert renpy.loadable(cs_darya_piano_track) and renpy.loadable(cs_miku_piano_track)','    assert renpy.loadable("sound/ambiences/music_club_day.ogg")','    run Start("cs_qa_part02_load")','    pause 1.0','    $ cs_friend_mi = 0','    $ cs_day02_miku_listened = None','    run Jump("cs_qa_part02_path")','    click until label cs_check_part02_japanese','    pause 1.0','    assert renpy.showing("cs_camp_path_day")','    $ cs_qa_capture("'+name+'_japanese")','    click until label cs_check_part02_s17','    pause 2.5','    assert renpy.music.get_playing() is None','    $ cs_qa_capture("'+name+'_club")','    click until label cs_check_d2_piano_darya','    pause 2.0','    assert renpy.showing("cs_cg_darya_piano_day")','    assert not renpy.showing("cs_darya") and not renpy.showing("mi")','    assert renpy.music.get_playing(channel="cs_piano") == cs_darya_piano_track','    $ cs_qa_capture("'+name+'_darya_piano")','    $ renpy.take_screenshot()','    $ renpy.save("'+name+'-piano")','    $ cs_friend_mi = 99','    $ renpy.load("'+name+'-piano")','    pause 1.0','    assert cs_friend_mi == 0 and renpy.showing("cs_cg_darya_piano_day")','    click until label cs_check_part02_menu','    pause 1.0','    assert cs_met_mi and cs_mi_name_known','    assert renpy.music.get_playing(channel="cs_piano") is None','    $ cs_qa_capture("'+name+'_menu")','    $ renpy.take_screenshot()','    $ renpy.save("'+name+'-menu")','    $ cs_friend_mi = 99','    $ renpy.load("'+name+'-menu")','    pause 1.0','    assert cs_friend_mi == 0','    "'+choice+'"']
 if listen:
  out+=['    click until label cs_check_d2_piano_miku','    pause 2.0','    assert cs_friend_mi == 1','    assert renpy.showing("cs_cg_miku_piano_day")','    assert not renpy.showing("mi") and not renpy.showing("cs_darya")','    assert renpy.music.get_playing(channel="cs_piano") == cs_miku_piano_track','    $ cs_qa_capture("'+name+'_miku_piano")','    click until label cs_check_d2_piano_miku_again','    pause 2.0','    assert renpy.showing("cs_cg_miku_piano_day")','    $ cs_qa_capture("'+name+'_miku_again")']
 out+=['    click until label cs_check_part02_s20','    assert cs_friend_mi == '+str(int(listen)),'    pause 1.0','    assert not renpy.showing("mi") and not renpy.showing("cs_semen")','    assert renpy.music.get_playing(channel="cs_piano") is None','    click until label cs_check_part02_square','    pause 1.0','    assert renpy.showing("bg ext_square_day")','    $ cs_qa_capture("'+name+'_square")','    click until label cs_check_part02_pending','    pause 1.0','    assert not cs_day02_done and cs_friend_mi == '+str(int(listen)),'    $ cs_qa_capture("'+name+'_end")']
 if listen:
  out+=['    run Jump("cs_qa_part02_replay")','    click until label cs_check_part02_menu','    "Остаться и послушать репетицию Мику"','    click until label cs_check_part02_pending','    pause 1.0','    assert cs_friend_mi == 1']
 out+=['    $ open(config.gamedir + "/mods/chuzaya_smena/qa/'+name+'_pass.txt", "w").write("PASS")','    run Quit(confirm=False)','']
(R/'qa/part02_routes_test.rpy').write_text('\n'.join(out),encoding='utf8')
print('Two performance/choice/save-load cases generated')
